// Generated by AI (UnitTest MCP)
//! Board, next-task, and existing-work queries.

use super::claim::{intersect_paths, task_scope_on};
use super::*;

impl LodestarStore {
    /// The next unblocked, claimable task, oldest first: open, lease-expired, or
    /// a parked task past its parking grace (ADR-0020). Parked tasks still within
    /// grace are owned and deliberately not surfaced here.
    pub fn next_task(&self, now: i64) -> Result<Option<Task>> {
        let parked_cutoff = now - PARKING_GRACE_SECS;
        let sql = format!(
            "SELECT {TASK_COLS} FROM tasks
              WHERE blocked_by IS NULL
                AND (status = 'open'
                     OR (status = 'claimed' AND lease_expires_at < ?1)
                     OR (status IN ('needs_input', 'paused')
                         AND parked_at IS NOT NULL AND parked_at < ?2))
              ORDER BY created_at ASC LIMIT 1"
        );
        let mut stmt = self.conn.prepare(&sql)?;
        let mut rows = stmt.query(params![now, parked_cutoff])?;
        match rows.next()? {
            Some(row) => Ok(Some(row_to_task(row)?)),
            None => Ok(None),
        }
    }

    pub fn board(&self, include_terminal: bool) -> Result<Vec<Task>> {
        let sql = if include_terminal {
            format!("SELECT {TASK_COLS} FROM tasks ORDER BY created_at ASC")
        } else {
            format!(
                "SELECT {TASK_COLS} FROM tasks \
                 WHERE status NOT IN ('done', 'abandoned') ORDER BY created_at ASC"
            )
        };
        let mut stmt = self.conn.prepare(&sql)?;
        let rows = stmt.query_map([], row_to_task)?;
        collect(rows)
    }

    /// Diagnose the live board: the conditions that no other view surfaces.
    ///
    /// Read-only and judgement-free. It reports what it finds and suggests a
    /// repair; it never abandons, blocks, or reopens anything, because which of
    /// two identically titled tasks is the real work is a call only the reader
    /// can make (ADR-0015).
    ///
    /// Terminal tasks are excluded throughout. A retired duplicate is history,
    /// and reporting it would make the view noisier every time it was acted on
    /// — which is how a diagnostic stops being read.
    pub fn diagnose_board(&self) -> Result<Vec<BoardFinding>> {
        let live = self.board(false)?;
        let mut findings = Vec::new();

        let mut by_title: Vec<(&str, Vec<&Task>)> = Vec::new();
        for task in &live {
            match by_title.iter_mut().find(|(title, _)| *title == task.title) {
                Some((_, group)) => group.push(task),
                None => by_title.push((task.title.as_str(), vec![task])),
            }
        }

        for (title, group) in &by_title {
            if group.len() < 2 {
                continue;
            }
            // One title can be both at once: two under one goal and a third
            // elsewhere is a fork *and* a duplicate, and a reader told only the
            // first would retire the wrong one.
            let mut same_goal: Vec<String> = Vec::new();
            let mut across_goals: Vec<String> = Vec::new();
            for task in group {
                let slug = goal_slug(&task.goal_id);
                if group
                    .iter()
                    .any(|other| other.id != task.id && goal_slug(&other.goal_id) == slug)
                {
                    same_goal.push(task.id.clone());
                }
                if group.iter().any(|other| goal_slug(&other.goal_id) != slug) {
                    across_goals.push(task.id.clone());
                }
            }
            if !same_goal.is_empty() {
                findings.push(BoardFinding {
                    ailment: BoardAilment::DuplicateTitle,
                    task_ids: same_goal,
                    subject: (*title).to_string(),
                    remedy: "one goal, one title, more than one live task: decide which is \
                             the work and abandon the rest before two agents claim both"
                        .to_string(),
                });
            }
            if !across_goals.is_empty() {
                findings.push(BoardFinding {
                    ailment: BoardAilment::SameTitleAcrossGoals,
                    task_ids: across_goals,
                    subject: (*title).to_string(),
                    remedy: "the same title is live under several goals: keep the one whose \
                             goal the work actually serves, declare any genuine breadth with \
                             also_serves on that single task (ADR-0041), and abandon the rest"
                        .to_string(),
                });
            }
        }

        let stated_a_reason = self.blocks_that_stated_a_reason()?;
        for task in &live {
            if task.status == TaskStatus::Blocked
                && task.blocked_by.is_none()
                && !stated_a_reason.contains(&task.id)
            {
                findings.push(BoardFinding {
                    ailment: BoardAilment::BlockedWithoutGate,
                    task_ids: vec![task.id.clone()],
                    subject: task.title.clone(),
                    remedy: "blocked on no predecessor and with no reason recorded, so nothing \
                             will unblock it and nothing says what would: reopen it if the work \
                             is wanted, abandon it if it is not, or re-block it with a reason \
                             naming what clears it"
                        .to_string(),
                });
            }
        }

        Ok(findings)
    }

    /// Tasks whose most recent `blocked` event stated a reason.
    ///
    /// `blocked_by` is a one-to-one handoff (ADR-0015), so several tasks waiting
    /// on one predecessor cannot all be gated on it. A block with a stated
    /// reason is the only way to express that, and reporting it as an ailment
    /// would fire forever on a board that is behaving correctly.
    fn blocks_that_stated_a_reason(&self) -> Result<HashSet<String>> {
        let mut statement = self.conn.prepare(
            "SELECT task_id, detail FROM task_events e
             WHERE e.kind = ?1
               AND e.seq = (SELECT MAX(seq) FROM task_events x
                            WHERE x.task_id = e.task_id AND x.kind = ?1)",
        )?;
        let rows = statement.query_map(params![TaskEventKind::Blocked.as_str()], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
        })?;
        let mut stated = HashSet::new();
        for row in rows {
            let (task_id, detail) = row?;
            // Written by `detail_json`, so read it the same way rather than
            // matching on the text.
            let reason = serde_json::from_str::<serde_json::Value>(&detail)
                .ok()
                .and_then(|detail| detail.get("reason")?.as_str().map(str::to_string));
            if reason.is_some_and(|reason| !reason.trim().is_empty()) {
                stated.insert(task_id);
            }
        }
        Ok(stated)
    }

    /// Work that already serves this goal, or already declared any of these
    /// paths in its scope — including finished work.
    ///
    /// The question is "has this already been done", not "who is touching this
    /// file", so `done` and `abandoned` are included and a finished task is the
    /// most useful answer of all. `board` deliberately hides terminal tasks,
    /// which is right for a board and wrong for this.
    ///
    /// Path matching reuses `intersect_paths`, the same glob comparison
    /// `check_overlap` uses, so "does this scope cover that file" has one answer
    /// in this codebase rather than two that drift apart.
    ///
    /// Goal matching reuses `goal_slug` for the same reason. An amendment
    /// re-issues a clause as `goal:<slug>@constitution:vN` while tasks go on
    /// naming whichever form they were created under, so an exact compare
    /// answers "nothing exists" for work that plainly does — precisely when the
    /// question is being asked in order not to repeat it. The comparison lives
    /// in Rust rather than in a SQL `LIKE` so there is one implementation of
    /// "same goal" and not a second one to drift from it; this runs when a task
    /// is created, not in a hot loop.
    pub fn existing_work(&self, goal_id: Option<&str>, paths: &[String]) -> Result<Vec<Task>> {
        let mut found: Vec<Task> = Vec::new();
        let mut seen: HashSet<String> = HashSet::new();

        if let Some(goal_id) = goal_id {
            let slug = goal_slug(goal_id);
            let sql = format!("SELECT {TASK_COLS} FROM tasks ORDER BY created_at ASC");
            let mut stmt = self.conn.prepare(&sql)?;
            let rows = stmt.query_map([], row_to_task)?;
            for task in collect(rows)? {
                if goal_slug(&task.goal_id) == slug && seen.insert(task.id.clone()) {
                    found.push(task);
                }
            }
        }

        if !paths.is_empty() {
            let sql = format!(
                "SELECT {TASK_COLS} FROM tasks WHERE id IN (
                     SELECT task_id FROM task_scopes WHERE kind = 'path'
                 ) ORDER BY created_at ASC"
            );
            let mut stmt = self.conn.prepare(&sql)?;
            let rows = stmt.query_map([], row_to_task)?;
            for task in collect(rows)? {
                if seen.contains(&task.id) {
                    continue;
                }
                let scope = task_scope_on(&self.conn, &task.id)?;
                if !intersect_paths(paths, &scope.paths)?.is_empty() {
                    seen.insert(task.id.clone());
                    found.push(task);
                }
            }
        }

        found.sort_by_key(|task| task.created_at);
        Ok(found)
    }
}

#[cfg(test)]
mod tests {
    use crate::store::test_support::*;

    #[test]
    fn next_task_skips_blocked_and_prefers_oldest() {
        let s = store();
        let g = goal(&s);
        let first = s.create_task(&g.id, "first", "", None, NOW).unwrap();
        let second = s.create_task(&g.id, "second", "", None, NOW + 1).unwrap();
        s.block_task(&second.id, None, None, "human", NOW).unwrap();
        let next = s.next_task(NOW + 10).unwrap().unwrap();
        assert_eq!(next.id, first.id);
    }
}
